create table if not exists public.settings (key text primary key,value text not null default '');create table if not exists public.services (id bigint primary key,title text not null,description text not null default '',image text not null default '');create table if not exists public.site_admins (user_id uuid primary key references auth.users(id) on delete cascade);alter table public.settings enable row level security;alter table public.services enable row level security;alter table public.site_admins enable row level security;create policy "Public read settings" on public.settings for select to anon,authenticated using(true);create policy "Public read services" on public.services for select to anon,authenticated using(true);create policy "Admin self lookup" on public.site_admins for select to authenticated using(user_id=auth.uid());create policy "Admin edit settings" on public.settings for all to authenticated using(exists(select 1 from public.site_admins where user_id=auth.uid())) with check(exists(select 1 from public.site_admins where user_id=auth.uid()));create policy "Admin edit services" on public.services for all to authenticated using(exists(select 1 from public.site_admins where user_id=auth.uid())) with check(exists(select 1 from public.site_admins where user_id=auth.uid()));insert into storage.buckets(id,name,public) values('site-images','site-images',true) on conflict(id) do nothing;create policy "Admin image upload" on storage.objects for insert to authenticated with check(bucket_id='site-images' and exists(select 1 from public.site_admins where user_id=auth.uid()));